<?php
namespace App\Services\Marketing;
use App\Models\{MarketingAiRun,MarketingVideoFilm,MarketingProject,MarketingConversationMessage};
use Illuminate\Support\Facades\{DB,Cache,Validator};use App\Jobs\ProcessMarketingOptimization;
class MarketingOptimization {
 public const ACTION='film_optimization';
 public function film(string $project,int $owner,string $id):MarketingVideoFilm{app(MarketingClipSource::class)->project($project,$owner);$f=MarketingVideoFilm::where('project_id',$project)->where('owner_id',$owner)->where('status','completed')->findOrFail($id);app(MarketingWorkspaceFilm::class)->assertCurrent($f);app(MarketingVideoFiles::class)->file($f->output_path,$f->output_sha256);return $f;}
 public function enqueue(string $project,int $owner,string $film,string $hash,string $request,bool $recheck=false):MarketingAiRun {
  abort_unless(MarketingEditingConversation::enabled(),403,'优化检查尚未开放。');$f=$this->film($project,$owner,$film);abort_unless(hash_equals($f->output_sha256,$hash),409,'成片版本已变化，请重新读取。');
  return DB::transaction(function()use($project,$owner,$f,$request,$recheck){MarketingProject::whereKey($project)->lockForUpdate()->firstOrFail();$old=MarketingAiRun::where('project_id',$project)->where('request_id',$request)->first();if($old){abort_unless($old->action===self::ACTION&&($old->usage['film_id']??null)===$f->id&&($old->usage['base_hash']??null)===$f->output_sha256,409);return $old;}
   if(!$recheck){$existing=MarketingAiRun::where('project_id',$project)->where('action',self::ACTION)->where('usage->film_id',$f->id)->where('usage->base_hash',$f->output_sha256)->latest()->first();if($existing)return $existing;}
   $pending=MarketingAiRun::where('project_id',$project)->where('action',self::ACTION)->whereIn('status',['queued','running'])->latest()->first();if($pending){if($pending->updated_at->lt(now()->subMinutes(20)))$this->unknown($pending->id);else abort(409,'上一轮优化仍在处理中，请读取现有任务。');}
   $r=MarketingAiRun::create(['project_id'=>$project,'request_id'=>$request,'action'=>self::ACTION,'status'=>'queued','usage'=>['owner_id'=>$owner,'film_id'=>$f->id,'base_hash'=>$f->output_sha256,'recipe_digest'=>MarketingEditingDigest::hash($f->input),'model'=>MarketingOptimizationClient::MODEL,'stage'=>'queued','publication_authorized'=>false,'new_generation_requests'=>0]]);ProcessMarketingOptimization::dispatch($r->id);return $r;
  });
 }
 private function state(MarketingAiRun $r,string $stage,array $extra=[]):void{$r->refresh();$r->update(['usage'=>array_replace($r->usage??[],$extra,['stage'=>$stage])]);}
 public function process(string $id):void {
  $lock=Cache::lock('optimization:'.$id,1200);if(!$lock->get())return;$called=false;
  try{$r=MarketingAiRun::findOrFail($id);if($r->action!==self::ACTION||$r->status!=='queued')return;$r->update(['status'=>'running']);$u=$r->usage;$f=$this->film($r->project_id,$u['owner_id'],$u['film_id']);abort_unless(hash_equals($u['base_hash'],$f->output_sha256)&&hash_equals($u['recipe_digest'],MarketingEditingDigest::hash($f->input)),409);
   $this->state($r,'sampling');$e=app(MarketingOptimizationEvidence::class)->collect($f,$r->id);$this->state($r,'analysis',['sample_count'=>count($e['samples'])]);$called=true;$this->state($r,'analysis',['request_claimed_at'=>now()->toIso8601String()]);$result=app(MarketingOptimizationClient::class)->inspect($e);$this->state($r,'validating',['provider_usage'=>$result['usage'],'response_model'=>$result['model'],'response_id'=>$result['response_id']]);
   $this->film($r->project_id,$u['owner_id'],$u['film_id']);$answer=$this->validateAnswer($f,$e,$result['answer']);$this->state($r,'completed',['answer'=>$answer,'evidence'=>$e,'completed_at'=>now()->toIso8601String()]);$r->update(['status'=>'completed','error'=>null]);
  }catch(\Throwable $err){if(isset($r)){$this->state($r,$called?'unknown':'failed',['automatic_retry'=>false,'error_type'=>class_basename($err),'validation_fields'=>$err instanceof \Illuminate\Validation\ValidationException?array_keys($err->errors()):[]]);$r->update(['status'=>$called?'unknown':'failed','error'=>$called?'优化未完成或回复未通过检查，未制作；没有自动重试。可核对后重新发起。':'素材检查未完成，原版保留；请检查来源后重新发起。']);}report($err);}finally{$lock->release();}
 }
 public function validateAnswer(MarketingVideoFilm $f,array $e,array $a):array {
  Validator::make($a,['summary'=>'required|string|max:2000','scope'=>'required|string|max:1500','preserve'=>'present|array|max:12','preserve.*'=>'string|max:800','unknowns'=>'present|array|max:12','unknowns.*'=>'string|max:800','recommendations'=>'present|array|max:6','recommendations.*'=>'array:capability,action,target_id,scene_number,patch,title,reason,evidence_ids,confidence,user_check','recommendations.*.capability'=>'required|in:'.implode(',',array_keys(MarketingOptimizationPlan::FIELDS)),'recommendations.*.action'=>'required|in:keep,remove,adjust,add','recommendations.*.target_id'=>'present|string|max:100','recommendations.*.scene_number'=>'required|integer|between:0,12','recommendations.*.patch'=>'present|array','recommendations.*.title'=>'required|string|max:100','recommendations.*.reason'=>'required|string|max:1600','recommendations.*.evidence_ids'=>'present|array|max:36','recommendations.*.evidence_ids.*'=>'string|in:'.implode(',',array_column($e['samples'],'id')),'recommendations.*.confidence'=>'required|in:high,uncertain','recommendations.*.user_check'=>'present|string|max:1000'])->validate();
  $plan=app(MarketingOptimizationPlan::class);$rows=app(MarketingOptimizationEvidence::class)->rows($f);$p=MarketingProject::findOrFail($f->project_id);$out=[];$seen=[];
  foreach($a['recommendations'] as $n=>$rec){$rec['id']='suggestion-'.($n+1);$rec['patch']=array_filter($rec['patch'],fn($v)=>$v!==null);$rec['selectable']=false;$rec['needs_speech_optin']=false;
   try{abort_if(!$rec['evidence_ids']&&$rec['action']!=='keep',422);$target=$rec['capability'].':'.$rec['target_id'];abort_if(isset($seen[$target]),422);$seen[$target]=true;$state=$plan->apply($e['current'],[$rec],[$rec['id']]);
    if($state['speed']&&(float)$state['speed']['rate']!==1.0&&$rec['capability']==='speed'){$s=collect($rows)->firstWhere('number',$state['speed']['scene_number']);$words=$s['words']??[];$speech=trim($s['spoken_text']??'')!==''&&(!$words||collect($words)->contains(fn($w)=>preg_match('/[\p{L}\p{N}]/u',$w['text'])&&$w['start_frame']<$state['speed']['end_frame']&&$w['end_frame']>$state['speed']['start_frame']));if($speech){$rec['needs_speech_optin']=true;$state['speed']['protect']=false;}}
    $plan->validateState($state,$rows,$p);$rec['selectable']=$rec['action']!=='keep'&&MarketingEditingDigest::hash($state)!==MarketingEditingDigest::hash($e['current']);$rec['default_selected']=$rec['selectable']&&$rec['confidence']==='high'&&!$rec['needs_speech_optin'];
   }catch(\Throwable){$rec['unavailable_reason']='此项尚不能可靠映射到现有控件，仅供讨论；不会执行。';$rec['default_selected']=false;}
   $out[]=$rec;
  }$a['recommendations']=$out;return $a;
 }
 public function read(string $project,int $owner,string $film,?string $runId=null):?MarketingAiRun {
  $f=$this->film($project,$owner,$film);$q=MarketingAiRun::where('project_id',$project)->where('action',self::ACTION);$r=$runId?$q->findOrFail($runId):$q->where('usage->film_id',$film)->latest()->first();if(!$r)return null;abort_unless(($r->usage['owner_id']??null)===$owner&&($r->usage['film_id']??null)===$film&&hash_equals($r->usage['base_hash'],$f->output_sha256),409);
  if(in_array($r->status,['queued','running'])&&$r->updated_at->lt(now()->subMinutes(20))){$this->unknown($r->id);$r->refresh();}return $r;
 }
 public function unknown(string $id):void{$r=MarketingAiRun::where('action',self::ACTION)->find($id);if($r&&in_array($r->status,['queued','running'])){$this->state($r,'unknown',['automatic_retry'=>false]);$r->update(['status'=>'unknown','error'=>'检查任务已中断，外部结果可能未知；原版保留，不自动重试。']);}}
 public function adopt(MarketingAiRun $r,string $request,array $selected,bool $speech=false):MarketingVideoFilm {
  abort_unless($r->status==='completed'&&count($selected)>0,422,'请选择建议，或保持原样。');$u=$r->usage;$f=$this->film($r->project_id,$u['owner_id'],$u['film_id']);abort_unless(hash_equals($u['base_hash'],$f->output_sha256)&&hash_equals($u['recipe_digest'],MarketingEditingDigest::hash($f->input)),409,'成片或配方已变化，请重新检查。');$recs=$u['answer']['recommendations'];foreach($selected as $id){$rec=collect($recs)->firstWhere('id',$id);abort_unless($rec&&$rec['selectable'],422,'所选建议不可执行。');abort_if($rec['needs_speech_optin']&&!$speech,422,'需要先试听并明确允许口播变速。');}
  $plan=app(MarketingOptimizationPlan::class);$state=$plan->apply($plan->baseline($f),$recs,$selected);if($speech&&collect($recs)->contains(fn($v)=>in_array($v['id'],$selected,true)&&$v['needs_speech_optin'])&&$state['speed'])$state['speed']['protect']=false;$rows=app(MarketingOptimizationEvidence::class)->rows($f);$state=$plan->validateState($state,$rows,MarketingProject::findOrFail($f->project_id));
  $sub=$state['subtitles']!==$plan->baseline($f)['subtitles']?app(MarketingSubtitleService::class)->plan($f,$state['subtitles']):null;
  return DB::transaction(function()use($r,$f,$request,$state,$sub,$selected,$speech){$locked=MarketingAiRun::lockForUpdate()->findOrFail($r->id);$receipts=$locked->usage['adoptions']??[];$selection=MarketingEditingDigest::hash(['selected'=>$selected,'speech'=>$speech]);if(isset($receipts[$request])){abort_unless($receipts[$request]['selection']===$selection,409);return MarketingVideoFilm::where('project_id',$r->project_id)->where('owner_id',$f->owner_id)->findOrFail($receipts[$request]['film_id']);}
   $new=app(MarketingFilmPackaging::class)->prepare($f->project_id,$f->owner_id,$request,$f->id,$f->output_sha256,$state['settings'],$sub,$state['information_cards'],$state['framing'],$state['emphasis'],$state['overlays'],$state['speed'],true);$receipts[$request]=['film_id'=>$new->id,'selection'=>$selection,'selected'=>$selected];$this->state($locked,'completed',['adoptions'=>$receipts]);return $new;
  });
 }
 public function present(?MarketingAiRun $r):?array{if(!$r)return null;$u=$r->usage;return ['id'=>$r->id,'status'=>$r->status,'stage'=>$u['stage'],'model'=>$u['model'],'base_film_id'=>$u['film_id'],'base_hash'=>$u['base_hash'],'error'=>$r->error,'answer'=>$u['answer']??null,'sample_count'=>$u['sample_count']??0,'samples'=>array_map(fn($s)=>array_intersect_key($s,array_flip(['id','frame','seconds'])),$u['evidence']['samples']??[]),'audio'=>$u['evidence']['audio']??null,'adoptions'=>array_values($u['adoptions']??[]),'automatic_retry'=>false,'one_click'=>app(MarketingOneClickOptimization::class)->present($r)];}
}
